const output = String($json.stdout ?? '');
const THRESHOLD = 90;
const alerts = [];
const checked = [];

let currentHost = 'Unknown host';

const ignored = new Set([
  'tmpfs','devtmpfs','efivarfs','squashfs','overlay','proc','sysfs',
  'cgroup','cgroup2','pstore','debugfs','securityfs','tracefs',
  'configfs','fusectl','hugetlbfs','mqueue','ramfs','autofs','binfmt_misc'
]);

for (const raw of output.split(/\r?\n/)) {
  const line = raw.trim();
  if (!line) continue;

  const host = line.match(/^(.+?)\s+\|\s+(?:CHANGED|SUCCESS|FAILED|UNREACHABLE)\s+\|/i);
  if (host) {
    currentHost = host[1].trim();
    continue;
  }

  if (line.startsWith('[WARNING]')) continue;

  // df -hP:
  // Filesystem Size Used Avail Use% Mounted_on
  const m = line.match(/^(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\d+)%\s+(.+)$/);
  if (!m) continue;

  const filesystem = m[1];
  const percent = Number(m[5]);
  const mountpoint = m[6];

  if (!Number.isFinite(percent)) continue;
  if (ignored.has(filesystem.toLowerCase())) continue;
  if (/^(proc|sysfs|cgroup|cgroup2|pstore|debugfs|securityfs|tracefs|configfs|fusectl|hugetlbfs|mqueue|ramfs|autofs|binfmt_misc)/i.test(filesystem)) continue;

  const row = {
    host: currentHost,
    filesystem,
    size: m[2],
    used: m[3],
    available: m[4],
    usage_percent: percent,
    mountpoint
  };

  checked.push(row);
  if (percent >= THRESHOLD) alerts.push(row);
}

const esc = v => String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const status = alerts.length ? 'CRITICAL' : 'HEALTHY';

const rows = alerts.length
  ? alerts.map((r,i) => `<tr>
<td style="padding:8px;border:1px solid #ddd">${i+1}</td>
<td style="padding:8px;border:1px solid #ddd">${esc(r.host)}</td>
<td style="padding:8px;border:1px solid #ddd;font-family:monospace">${esc(r.filesystem)}</td>
<td style="padding:8px;border:1px solid #ddd">${esc(r.mountpoint)}</td>
<td style="padding:8px;border:1px solid #ddd">${esc(r.size)}</td>
<td style="padding:8px;border:1px solid #ddd">${esc(r.used)}</td>
<td style="padding:8px;border:1px solid #ddd">${esc(r.available)}</td>
<td style="padding:8px;border:1px solid #ddd"><b>${r.usage_percent}%</b></td>
</tr>`).join('')
  : `<tr><td colspan="8" style="padding:10px;border:1px solid #ddd">No filesystem has reached ${THRESHOLD}%.</td></tr>`;

const html = `<!DOCTYPE html>
<html><body style="font-family:Arial;background:#f5f6f8;padding:20px">
<table width="100%" style="max-width:1000px;margin:auto;background:#fff;border:1px solid #ddd;border-collapse:collapse">
<tr><td style="padding:20px;background:#1f2937;color:white">
<h2>Linux Disk Utilization Alert</h2>
<p>Ansible / df -hP monitoring report</p>
</td></tr>
<tr><td style="padding:20px">
<p>Dear IT Team,</p>
<table width="100%" style="border-collapse:collapse">
<tr><td style="padding:8px;border:1px solid #ddd"><b>Report Time</b></td><td style="padding:8px;border:1px solid #ddd">${esc(new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd"><b>Threshold</b></td><td style="padding:8px;border:1px solid #ddd">${THRESHOLD}%</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd"><b>Status</b></td><td style="padding:8px;border:1px solid #ddd"><b>${status}</b></td></tr>
<tr><td style="padding:8px;border:1px solid #ddd"><b>Filesystems >= ${THRESHOLD}%</b></td><td style="padding:8px;border:1px solid #ddd"><b>${alerts.length}</b></td></tr>
</table>
<h3>Disk Space Alerts</h3>
<table width="100%" style="border-collapse:collapse">
<tr style="background:#dc2626;color:white">
<th>#</th><th>Server</th><th>Filesystem</th><th>Mount</th><th>Size</th><th>Used</th><th>Available</th><th>Use%</th>
</tr>${rows}</table>
<p><b>Action Required:</b> Investigate any filesystem at or above ${THRESHOLD}% utilization.</p>
<p>Regards,<br><b>IT Team</b><br>Ninestars Information Technologies Pvt Ltd</p>
</td></tr></table>
</body></html>`;

return [{
  json: {
    status,
    threshold: THRESHOLD,
    alert_count: alerts.length,
    alerts,
    checked_filesystems: checked.length,
    graphBody: {
      message: {
        subject: `Linux Disk Alert - ${status} - ${alerts.length} filesystem(s) >= ${THRESHOLD}%`,
        body: { contentType: 'HTML', content: html },
        toRecipients: [{emailAddress: {address: 'prem.d@ninestars.in'}}]
      },
      saveToSentItems: true
    }
  }
}];

